INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginne ich hier ohne Risiken zu prüfen?', 2, '[{"text": "Nein", "correct": true, "because": "Risiken identifizieren ist erster Schritt"}, {"text": "Ja", "correct": false, "because": "Risikoorientierter Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt mache ich zuerst in diesem Prozess?', 3, '[{"text": "Risiken identifizieren", "correct": true, "because": "Risiken stehen im Fokus"}, {"text": "Prototyping", "correct": false, "because": "Folgt Risikoanalyse"}, {"text": "Bewerten", "correct": false, "because": "Später im Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zu diesem Zyklus?', 5, '[{"text": "Prototyping", "correct": true, "because": "Lösungen testen"}, {"text": "Nächsten Zyklus planen", "correct": true, "because": "Iterative Planung"}, {"text": "Einmalige Entwicklung", "correct": false, "because": "Zyklisch nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Risiken werden früh erkannt. b) Bewerten ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bewerten essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich in diesem Ablauf?', 4, '[{"text": "Risiken identifizieren", "correct": false, "because": "Kern des Modells"}, {"text": "Prototyping", "correct": false, "because": "Risiken testen"}, {"text": "Lineare Entwicklung", "correct": true, "because": "Zyklisch aufgebaut"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier nur einmal plane?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder Zyklus wird geplant"}, {"text": "Ja", "correct": false, "because": "Iterativer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase wähle ich, um Lösungen zu testen?', 3, '[{"text": "Prototyping", "correct": true, "because": "Prototypen erstellen"}, {"text": "Bewerten", "correct": false, "because": "Ergebnisse prüfen"}, {"text": "Fertig stellen", "correct": false, "because": "Ende des Projekts"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte reduzieren Unsicherheiten?', 5, '[{"text": "Risiken identifizieren", "correct": true, "because": "Probleme früh erkennen"}, {"text": "Prototyping", "correct": true, "because": "Lösungen ausprobieren"}, {"text": "Einmalige Bewertung", "correct": false, "because": "Zyklisch nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Prototyping ist zentral. b) Risiken werden ignoriert. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Risiken im Fokus"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Bewerten", "correct": false, "because": "Ergebnisse prüfen"}, {"text": "Nächsten Zyklus planen", "correct": false, "because": "Iterationen steuern"}, {"text": "Feste Deadlines", "correct": true, "because": "Risikoorientiert flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Bewerten hier einmalig?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder Zyklus bewertet"}, {"text": "Ja", "correct": false, "because": "Iterativer Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente fördern die Projektsicherheit?', 4, '[{"text": "Risiken identifizieren", "correct": true, "because": "Probleme früh angehen"}, {"text": "Prototyping", "correct": true, "because": "Lösungen validieren"}, {"text": "Lineare Schritte", "correct": false, "because": "Zyklisch aufgebaut"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier ohne Prototypen arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Prototyping ist Kern"}, {"text": "Ja", "correct": false, "because": "Testen von Lösungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich zu Beginn eines Zyklus?', 3, '[{"text": "Risiken identifizieren", "correct": true, "because": "Risiken im Fokus"}, {"text": "Fertig stellen", "correct": false, "because": "Ende des Projekts"}, {"text": "Bewerten", "correct": false, "because": "Später im Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nächsten Zyklus planen ist iterativ. b) Prototyping ist unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prototyping zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat dieser Ablauf?', 5, '[{"text": "Risikoreduktion", "correct": true, "because": "Frühe Identifikation"}, {"text": "Flexibilität", "correct": true, "because": "Iterative Anpassung"}, {"text": "Lineare Struktur", "correct": false, "because": "Zyklisch aufgebaut"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Prototyping", "correct": false, "because": "Lösungen testen"}, {"text": "Risiken identifizieren", "correct": false, "because": "Kern des Modells"}, {"text": "Einmalige Planung", "correct": true, "because": "Iterativ nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Fertigstellen der erste Schritt?', 3, '[{"text": "Nein", "correct": true, "because": "Risiken zuerst prüfen"}, {"text": "Ja", "correct": false, "because": "Ende des Projekts"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier nur einmal Prototypen erstelle?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder Zyklus nutzt Prototyping"}, {"text": "Ja", "correct": false, "because": "Iterativer Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich nach dem Prototyping?', 4, '[{"text": "Bewerten", "correct": true, "because": "Prototypen prüfen"}, {"text": "Risiken identifizieren", "correct": false, "because": "Vor Prototyping"}, {"text": "Fertig stellen", "correct": false, "because": "Ende des Projekts"}]');
